package io.knowledgebrain.learning;
import java.time.*;
import java.util.*;
import org.flywaydb.core.Flyway;
import org.postgresql.ds.PGSimpleDataSource;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.web.server.ResponseStatusException;
import org.junit.jupiter.api.*;
import org.junit.jupiter.api.condition.EnabledIfEnvironmentVariable;
import static org.junit.jupiter.api.Assertions.*;

@EnabledIfEnvironmentVariable(named="BRAIN_TEST_LEARNING_DATABASE_URL",matches=".+")
class LearningStudyStoreIntegrationTest {
 Clock clock=Clock.fixed(Instant.parse("2026-10-15T10:00:00Z"),ZoneOffset.UTC);String trace="d".repeat(32);RoadmapStore roadmaps;LearningStudyStore store;JdbcTemplate sql;UUID space,actor,roadmap,a,b;RoadmapStore.Roadmap root;
 @BeforeEach void setup(){var ds=new PGSimpleDataSource();ds.setURL(System.getenv("BRAIN_TEST_LEARNING_DATABASE_URL"));ds.setUser("brain_learning");ds.setPassword(System.getenv("BRAIN_TEST_LEARNING_DATABASE_PASSWORD"));Flyway.configure().dataSource(ds).locations("classpath:db/migration").load().migrate();roadmaps=new RoadmapStore(ds,clock);store=new LearningStudyStore(ds,clock,roadmaps);sql=new JdbcTemplate(ds);var ids=new UuidV7(clock);space=ids.next();actor=ids.next();root=roadmaps.create(space,actor,"Tracking","Original roadmap",trace);roadmap=root.roadmapId();root=roadmaps.graph(space,roadmap,actor,1,new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit("new:a","First",""),new RoadmapGraph.NodeEdit("new:b","Second","")),List.of(new RoadmapGraph.EdgeEdit("new:e","PREREQUISITE_OF","new:a","new:b"))),trace);a=root.nodes().getFirst().nodeId();b=root.nodes().getLast().nodeId();}
 String key(){return UUID.randomUUID().toString().replace("-","");}
 LearningStudyStore.Input input(UUID node){return new LearningStudyStore.Input(node,"2026-10-15T17:00:00+09:00","2026-10-15T17:30:00+09:00","Raw note\n<script>literal</script>");}
 int events(String type,UUID id){return sql.queryForObject("SELECT count(*) FROM outbox_event WHERE aggregatetype=? AND aggregateid=?",Integer.class,type,id);}
 void status(int code,Runnable action){assertEquals(code,assertThrows(ResponseStatusException.class,action::run).getStatusCode().value());}
 @Test void manualProgressHasIndependentVersionsNoOpHistoryAndUnchangedRoadmap(){var initial=store.progress(space,roadmap,a);assertEquals(0,initial.version());assertNull(initial.progressId());assertEquals(initial,store.progress(space,roadmap,a,actor,0,"NOT_STARTED",trace));var one=store.progress(space,roadmap,a,actor,0,"IN_PROGRESS",trace);assertEquals(7,one.progressId().version());var two=store.progress(space,roadmap,a,actor,1,"COMPLETED",trace);assertEquals(2,two.version());assertEquals(two,store.progress(space,roadmap,a,actor,2,"COMPLETED",trace));status(412,()->store.progress(space,roadmap,a,actor,1,"COMPLETED",trace));var summary=store.summary(space,roadmap);assertEquals(2,summary.total());assertEquals(1,summary.completed());assertEquals(50,summary.percent());assertEquals(0,summary.recordedSeconds());assertEquals(0,store.progress(space,roadmap,b).version());assertEquals(List.of(2L,1L),store.progressHistory(space,roadmap,a,Long.MAX_VALUE,5).stream().map(LearningStudyStore.ProgressRevision::version).toList());assertEquals(one,store.progressHistory(space,roadmap,a,2,5).getFirst().snapshot());assertEquals(root,roadmaps.get(space,roadmap));assertEquals(2,events("roadmap",roadmap));assertEquals(2,events("progress",one.progressId()));}
 @Test void sessionIdempotencyKeepsOriginalIdentityAndReturnsCurrentRevisionOnReplay(){String key=key();var created=store.record(space,roadmap,actor,key,input(a),trace);assertTrue(created.created());var one=created.session();assertEquals(7,one.sessionId().version());assertEquals("2026-10-15T08:00:00Z",one.startedAt());assertEquals(1800,one.durationSeconds());assertEquals("NOT_STARTED",store.progress(space,roadmap,a).status());assertEquals(1800,store.summary(space,roadmap).recordedSeconds());var replay=store.record(space,roadmap,actor,key,new LearningStudyStore.Input(a,one.startedAt(),one.endedAt(),one.note()),trace);assertFalse(replay.created());assertEquals(one,replay.session());status(409,()->store.record(space,roadmap,actor,key,input(b),trace));var two=store.changeSession(space,roadmap,one.sessionId(),actor,1,new LearningStudyStore.Input(a,one.startedAt(),"2026-10-15T08:20:00Z","Corrected"),false,trace);assertEquals(1200,two.durationSeconds());assertEquals(two,store.record(space,roadmap,actor,key,input(a),trace).session());assertEquals(two,store.changeSession(space,roadmap,one.sessionId(),actor,2,new LearningStudyStore.Input(a,two.startedAt(),two.endedAt(),two.note()),false,trace));status(412,()->store.changeSession(space,roadmap,one.sessionId(),actor,1,input(a),false,trace));store.changeSession(space,roadmap,one.sessionId(),actor,2,null,true,trace);var last=store.record(space,roadmap,actor,key,input(a),trace);assertFalse(last.created());assertEquals("RETIRED",last.session().state());assertEquals(0,store.summary(space,roadmap).recordedSeconds());assertEquals(one,store.sessionHistory(space,roadmap,one.sessionId(),2,5).getFirst().snapshot());assertEquals(3,events("study-session",one.sessionId()));assertEquals(root,roadmaps.get(space,roadmap));}
 @Test void concurrentFirstProgressWritesHaveOneWinnerAndConcurrentSessionRetriesHaveOneRecord()throws Exception{try(var pool=java.util.concurrent.Executors.newFixedThreadPool(2)){var barrier=new java.util.concurrent.CyclicBarrier(2);var calls=new ArrayList<java.util.concurrent.Future<Boolean>>();for(String state:List.of("IN_PROGRESS","COMPLETED"))calls.add(pool.submit(()->{barrier.await();try{store.progress(space,roadmap,a,actor,0,state,trace);return true;}catch(ResponseStatusException e){assertEquals(412,e.getStatusCode().value());return false;}}));assertNotEquals(calls.get(0).get(),calls.get(1).get());var key=key();var gate=new java.util.concurrent.CyclicBarrier(2);var first=pool.submit(()->{gate.await();return store.record(space,roadmap,actor,key,input(a),trace);});var second=pool.submit(()->{gate.await();return store.record(space,roadmap,actor,key,input(a),trace);});var x=first.get();var y=second.get();assertNotEquals(x.created(),y.created());assertEquals(x.session(),y.session());assertEquals(1,events("study-session",x.session().sessionId()));}assertEquals(1,store.progress(space,roadmap,a).version());assertEquals(1,store.sessions(space,roadmap,null,20).items().size());}
 @Test void retiredNodesAndRoadmapKeepProgressAndSessionHistoryWithoutRestoringOrCountingArchivedNodes(){var progress=store.progress(space,roadmap,a,actor,0,"COMPLETED",trace);String key=key();var session=store.record(space,roadmap,actor,key,input(a),trace).session();var keep=root.nodes().getLast();roadmaps.graph(space,roadmap,actor,2,new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit(keep.nodeId().toString(),keep.title(),keep.description())),List.of()),trace);var summary=store.summary(space,roadmap);assertEquals(1,summary.total());assertEquals(0,summary.completed());assertEquals(0,summary.recordedSeconds());status(404,()->store.progress(space,roadmap,a));status(404,()->store.progress(space,roadmap,a,actor,1,"IN_PROGRESS",trace));status(404,()->store.record(space,roadmap,actor,key(),input(a),trace));assertEquals(session,store.session(space,roadmap,session.sessionId()));status(404,()->store.changeSession(space,roadmap,session.sessionId(),actor,1,input(a),false,trace));store.changeSession(space,roadmap,session.sessionId(),actor,1,null,true,trace);roadmaps.metadata(space,roadmap,actor,3,null,null,true,trace);status(404,()->store.summary(space,roadmap));status(404,()->store.progress(space,roadmap,b,actor,0,"COMPLETED",trace));assertEquals(progress,store.progressHistory(space,roadmap,a,Long.MAX_VALUE,5).getFirst().snapshot());assertEquals(session,store.sessionHistory(space,roadmap,session.sessionId(),2,5).getFirst().snapshot());assertEquals("RETIRED",store.record(space,roadmap,actor,key,input(a),trace).session().state());}
 @Test void invalidIntervalsOversizedNotesForeignNodesAndCrossSpaceNeverWrite(){var foreign=roadmaps.create(actor,actor,"Foreign","",trace);var graph=roadmaps.graph(actor,foreign.roadmapId(),actor,1,new RoadmapGraph.Edit(List.of(new RoadmapGraph.NodeEdit("new:f","Foreign","")),List.of()),trace);var other=graph.nodes().getFirst().nodeId();for(var input:List.of(new LearningStudyStore.Input(a,"bad","bad",""),new LearningStudyStore.Input(a,"2026-10-15T08:00:00Z","2026-10-15T08:00:00Z",""),new LearningStudyStore.Input(a,"2026-10-13T08:00:00Z","2026-10-15T08:00:00Z",""),new LearningStudyStore.Input(a,"2026-10-15T10:00:00Z","2026-10-15T10:10:00Z",""),new LearningStudyStore.Input(a,"2026-10-15T08:00:00Z","2026-10-15T08:01:00Z","가".repeat(2731))))status(400,()->store.record(space,roadmap,actor,key(),input,trace));status(404,()->store.record(space,roadmap,actor,key(),input(other),trace));status(404,()->store.record(actor,roadmap,actor,key(),input(a),trace));status(404,()->store.progress(space,roadmap,other,actor,0,"COMPLETED",trace));status(404,()->store.summary(actor,roadmap));assertTrue(store.sessions(space,roadmap,null,20).items().isEmpty());assertEquals(0,store.progress(space,roadmap,a).version());assertEquals(root,roadmaps.get(space,roadmap));}
 @Test void sessionsAndProgressHaveIndependentKeysetAndVersionHistoryAndPinnedNodeTitles(){var all=new ArrayList<LearningStudyStore.Session>();for(int n=0;n<22;n++)all.add(store.record(space,roadmap,actor,key(),input(a),trace).session());var first=store.sessions(space,roadmap,null,20);assertEquals(20,first.items().size());assertEquals(2,store.sessions(space,roadmap,first.nextAfter(),20).items().size());var one=all.getFirst();var nodes=root.nodes().stream().map(n->new RoadmapGraph.NodeEdit(n.nodeId().toString(),"Renamed "+n.title(),n.description())).toList();roadmaps.graph(space,roadmap,actor,2,new RoadmapGraph.Edit(nodes,root.edges().stream().map(e->new RoadmapGraph.EdgeEdit(e.edgeId().toString(),e.kind(),e.sourceNodeId().toString(),e.targetNodeId().toString())).toList()),trace);for(int n=1;n<8;n++)store.changeSession(space,roadmap,one.sessionId(),actor,n,new LearningStudyStore.Input(a,one.startedAt(),one.endedAt(),"Edit "+n),false,trace);var history=store.sessionHistory(space,roadmap,one.sessionId(),Long.MAX_VALUE,5);assertEquals(List.of(8L,7L,6L,5L,4L),history.stream().map(LearningStudyStore.SessionRevision::version).toList());assertEquals(List.of(3L,2L,1L),store.sessionHistory(space,roadmap,one.sessionId(),4,5).stream().map(LearningStudyStore.SessionRevision::version).toList());assertEquals(one.nodeTitle(),store.session(space,roadmap,one.sessionId()).nodeTitle());for(int n=0;n<8;n++)store.progress(space,roadmap,a,actor,n,n%2==0?"IN_PROGRESS":"COMPLETED",trace);assertEquals(5,store.progressHistory(space,roadmap,a,Long.MAX_VALUE,5).size());assertEquals(3,store.progressHistory(space,roadmap,a,4,5).size());assertEquals(8,events("study-session",one.sessionId()));}
}
